#pragma once

// Ship of Harkinian's Debug Warp Screen lists, generated by
// tools/oot3d/dev_warp/generate_dev_warp_catalog.py (developer builds only).

#include <array>
#include <cstddef>
#include <cstdint>
#include <span>

namespace Oot3dNativeGame {

// One warp destination. A grotto destination names its row in
// kDevWarpGrottos (Grotto >= 0); otherwise Entrance is a global entrance
// index whose scene and spawn are the ones SoH expects there.
struct DevWarpEntrance {
  const char *English;
  const char *German;
  const char *French;
  uint16_t Entrance;
  uint8_t Scene;
  uint8_t Spawn;
  int8_t Grotto;
};

// A scene of the Better Debug Warp Screen: its entrances are
// kDevWarpBetterEntrances[First, First + Count).
struct DevWarpScene {
  const char *English;
  const char *German;
  const char *French;
  uint16_t First;
  uint16_t Count;
  bool Grottos;
};

// SoH's BetterSceneSelectGrottoData: the grotto entrance, where leaving it
// returns (entrance, room, position) and the grotto content byte.
struct DevWarpGrotto {
  uint16_t Entrance;
  uint8_t Scene;
  uint8_t Spawn;
  uint16_t ReturnEntrance;
  uint8_t ReturnScene;
  uint8_t ReturnSpawn;
  int8_t ReturnRoom;
  uint8_t Data;
  uint8_t ExitScene;
  float ReturnPosition[3];
};

// Arrival options a title declares (MM3D: day, time, form). A selection
// holds one value per axis, in the title's axis order: a choice's Value, or
// kDevWarpKeep (leave the guest's value as it is) or kDevWarpPreset (the
// zone's suggestion; Keep outside a zone). OoT3D declares none: its age and
// day/night stay on the established Debug Warp Screen path.
inline constexpr size_t kDevWarpMaxAxes = 4;
inline constexpr int32_t kDevWarpKeep = -1;
inline constexpr int32_t kDevWarpPreset = -2;
using DevWarpSelection = std::array<int32_t, kDevWarpMaxAxes>;
inline constexpr DevWarpSelection kDevWarpKeepAll{kDevWarpKeep, kDevWarpKeep, kDevWarpKeep, kDevWarpKeep};
inline constexpr DevWarpSelection kDevWarpPresetAll{kDevWarpPreset, kDevWarpPreset, kDevWarpPreset,
                                                    kDevWarpPreset};

struct DevWarpChoice {
  const char *Label;
  int32_t Value;
};

struct DevWarpAxis {
  const char *Id;     // persistence and agent-hook key, e.g. "day"
  const char *Label;  // F1 label
  std::span<const DevWarpChoice> Choices;
  // The title's integration proof for writing this axis; an unproven axis is
  // shown with its reason and only Keep is accepted.
  bool Proven = false;
  const char *Pending = "";
};

// A curated destination: a catalog entrance with a suggested arrival.
struct DevWarpZone {
  const char *Id;
  const char *Category;
  const char *Name;
  const char *Note;
  uint16_t Entrance;
  DevWarpSelection Preset;
  // The zone's arrival has a reviewed live receipt.
  bool Proven;
};

#include "oot3d_dev_warp_catalog.inc"

inline std::span<const DevWarpEntrance> DevWarpVanillaEntrances() noexcept { return kDevWarpVanillaEntrances; }
inline std::span<const DevWarpEntrance> DevWarpBetterEntrances() noexcept { return kDevWarpBetterEntrances; }
inline std::span<const DevWarpScene> DevWarpBetterScenes() noexcept { return kDevWarpBetterScenes; }
inline std::span<const DevWarpGrotto> DevWarpGrottos() noexcept { return kDevWarpGrottos; }

} // namespace Oot3dNativeGame
